#!/usr/bin/env python3
"""Overview of every merged NS2 training flight of lab 2026-10-16/17 (and the relabelled v1 bank): settings, status, per-flight checks. Writes docs/ns2_training_data_overview_2026-10-17.md.
  ~/.pyenv/versions/flying_robots/bin/python experiments/analysis/ns2_data_overview.py"""
import json
from pathlib import Path
import numpy as np, pandas as pd
ROOT = Path(__file__).resolve().parents[2]
EXCL = {"18-02-54": "bottom drone reads z = 1.00 m from t ≈ 33 s (lost / merged tracking)", "18-26-13": "bottom drone reads z = 1.00 m the whole flight",
        "13-23-04": "contact (min distance 0.00 m), bottom drone above the top drone 4.4 s, residual spike +102 m/s²"}
rows = []
for bank in ("bank_ns2train_2026-10-16", "bank_ns2train_2026-10-17"):
    for f in json.load(open(ROOT / "experiments/logs" / bank / "training_manifest.json"))["flights"]:
        m = json.load(open(ROOT / f"experiments/logs/{f['scenario']}_{f['date']}_{f['stamp']}.meta.json")); P = m["params"]; du = m["duration"]
        hdr = pd.read_csv(ROOT / f["path"], comment="#", nrows=0).columns
        B = [c for c in hdr if c.startswith("cf5_")][0].split(".")[0] + "."; T = B.replace("cf5_", "cf_second_")
        d = pd.read_csv(ROOT / f["path"], comment="#"); w = d[(d.t >= 0) & (d.t <= du)]; t = w.t.values; dt = float(np.median(np.diff(t))); g = lambda p, c: w[p + c].values
        dx, dy, dz = g(T, "locsrv_x") - g(B, "locsrv_x"), g(T, "locsrv_y") - g(B, "locsrv_y"), g(T, "locsrv_z") - g(B, "locsrv_z")
        h = np.hypot(dx, dy); r = np.sqrt(h ** 2 + dz ** 2); k = max(1, int(0.1 / dt)); sm = lambda x: np.convolve(x, np.ones(k) / k, "same")
        gate = (abs(dx) < .2) & (abs(dy) < .2) & (abs(np.gradient(sm(g(T, "locsrv_x")), t) - np.gradient(sm(g(B, "locsrv_x")), t)) < 1.5) & (dz > 0)
        ez = 100 * g(B, "omar_err_pos_z"); ar = g(B, "a_res_z")
        sc = f["scenario"]
        if sc == "A8" and P.get("speed") is None and P.get("duration"):
            P = dict(P, speed=round(35.0 / 16.0 * float(P.get("span", 1.0)) / float(P["duration"]), 2))     # A8 is stored as a duration
        fmt = lambda *ks: ", ".join(f"{k} {P[k]}" for k in ks if k in P and P[k] is not None)
        setting = {"A8": fmt("dz", "speed"), "A2": fmt("dz", "speed"), "A3": fmt("dz", "speed"), "A1": fmt("dz"), "R1": fmt("seed"),
                   "A4": fmt("dz", "offset", "speed") + (", line along x" if P.get("rotate_deg", 0) == 0 else ", line along y"), "A9": fmt("speed") + ", 9 sections, line along y"}[sc]
        notes = []
        if f["stamp"] in EXCL: status, notes = "EXCLUDED", [EXCL[f["stamp"]]]
        else: status = "usable"
        if status == "usable":
            if r.min() < 0.15: notes.append(f"closest approach {r.min():.2f} m")
            if dt * (dz < 0).sum() > 0.5: notes.append(f"bottom above top {dt * (dz < 0).sum():.1f} s")
            if sc == "A1" or sc in ("A2",): pass
        rows.append(dict(date=f["date"][5:], time=f["stamp"].replace("-", ":"), scenario=sc, setting=setting, plan_s=round(du), gate_s=round(float(gate.sum() * dt), 1),
                         ez=round(float(np.sqrt((ez ** 2).mean())), 1), a_in=round(float(ar[gate].mean()), 2) if gate.any() else float("nan"), status=status, notes="; ".join(notes)))
D = pd.DataFrame(rows).sort_values(["scenario", "date", "time"]).reset_index(drop=True)
old = json.load(open(ROOT / "experiments/logs/bank_v1_relabelled/training_manifest.json")); old = old["flights"] if isinstance(old, dict) else old
oc = pd.Series([f["scenario"] for f in old]).value_counts().sort_index()
U = D[D.status == "usable"]
L = ["# NS2 training data overview — lab 2026-10-16/17 (S0, both drones controller 9, indi 0, NS2 off) plus the relabelled v1 bank", "",
     "Generated by `experiments/analysis/ns2_data_overview.py` from the merged banks (`experiments/logs/bank_ns2train_2026-10-16|17`, regenerate with `merge_training_bank.py --allow-short 2.0`). Raw uSD logs of both drones: `experiments/logs/usd_raw/*ns2train*`; radio CSV/meta: `experiments/logs/<SCEN>_<date>_<time>.*`. Per-flight metrics: `experiments/results/ns2_collection_2026-10-17/`. Session records: `docs/lab_sessions/2026-10-16.md`, `2026-10-17.md`. Models trained so far: `docs/ns2_model_registry.md`.", "",
     f"**Totals:** {len(D)} merged flights, **{len(U)} usable**, {int((D.status == 'EXCLUDED').sum())} excluded; **{U.gate_s.sum():.0f} s inside the NS2 gate** (|dx|,|dy| < 0.2 m, |dvx| < 1.5 m/s, neighbour above). Plus the **26 old v1 flights** ({', '.join(f'{k} {v}' for k, v in oc.items())}), relabelled with the tree definition (`bank_v1_relabelled`), used together with these in the pilot retrain. Caveat for all of them: the bottom (labelled) vehicle cf5 is slightly bent.", "",
     "## 1. By scenario", "", "| Scenario | What it is | Flights usable / merged | Gate s | Settings covered |", "|---|---|---|---|---|"]
desc = {"A8": "two drones swap sides (crossing)", "A2": "stacked circle r 0.40 m", "A3": "static top, bottom shuttles under it", "A1": "stacked hold 15 s", "R1": "random waypoints, stack-biased", "A4": "bottom offset sideways, shuttles along a line", "A9": "nine A4 settings chained in one flight"}
for sc in ["A8", "A2", "A3", "A1", "R1", "A4", "A9"]:
    s, u = D[D.scenario == sc], U[U.scenario == sc]
    L.append(f"| {sc} | {desc[sc]} | {len(u)} / {len(s)} | {u.gate_s.sum():.0f} | {'; '.join(sorted(set(u.setting.str.replace(', 9 sections, line along y', ''))))[:200]} |")
L += ["", "## 2. Every merged flight", "", "| Scenario | Date | Time | Setting | Plan s | Gate s | z error RMS cm | `a_res_z` in gate | Status | Notes |", "|---|---|---|---|---:|---:|---:|---:|---|---|"]
for _, r in D.iterrows():
    L.append(f"| {r.scenario} | {r.date} | {r.time} | {r.setting} | {r.plan_s} | {r.gate_s} | {r.ez} | {r.a_in} | {r.status} | {r.notes} |")
L += ["", "## 3. Flown but not usable (no log from both drones, or aborted)", "",
      "| Scenario | Time | Setting | Why |", "|---|---|---|---|"]
lost = [("A8", "10-16 17:16", "dz 0.5, 0.5 m/s", "cf_second file empty"), ("A8", "10-16 17:18", "dz 0.5, 0.5 m/s", "both files empty"), ("A2", "10-16 17:52", "dz 0.5, 0.5 m/s", "cf_second file empty (refly merged)"),
        ("A2", "10-16 17:55", "dz 0.5, 0.4 m/s", "both files empty"), ("A3", "10-16 18:30", "dz 0.5, 0.5 m/s", "cf_second file empty (refly merged)"), ("A3", "10-16 18:31", "dz 0.5, 0.1 m/s", "both files empty"),
        ("A8", "10-16 19:06", "dz 0.25, 0.1 m/s", "aborted at 26 s, cf_second file empty (19:08 merged)"), ("A8", "10-16 19:23", "dz 0.75, 0.3 m/s", "aborted, no logs (19:24 merged)"),
        ("A1", "10-16 19:38", "dz 0.25", "cf_second file empty (refly merged 10-17)"), ("A1", "10-16 19:40", "dz 0.5", "cf_second file empty (refly merged 10-17)"),
        ("A1", "10-16 19:43 / 19:44", "dz 0.75", "both files empty"), ("R1", "10-17 13:52 and 14:07", "seed 109", "drone near the boundary / lost, files empty; skipped for good"),
        ("A4", "10-17 14:12", "dz 0.5, offset 0.0", "no cf5 file")]
for r in lost: L.append("| " + " | ".join(r) + " |")
L += ["", "Not flown on purpose: A5 (≈ A8), A7 (same close-approach regime as R1; dz below 0.25 is outside the study range), A2/A3 repeats at dz 0.25/0.75, the A4 offset-0.05 speed sweeps, R1 seeds 111–120 and the unflown A4 settings (dz 0.5 offset 0.15; dz 0.25 and 0.75 as separate flights, covered inside A9 at 0.3 and 0.5 m/s)."]
Path(ROOT / "docs/ns2_training_data_overview_2026-10-17.md").write_text("\n".join(L) + "\n"); print(len(D), len(U), round(U.gate_s.sum()))
